APX.nl = {"country":{"name":"Netherlands","tagline":"Limburg marl, Achterhoek farms and fungus-resistant grapes: Dutch wine is young, small and growing fast.","classification":"Six PDOs registered between 2017 and 2020: Maasvallei Limburg (cross-border with Belgium), Mergelland, Vijlen, Oolde, Ambt Delden and Achterhoek-Winterswijk. Each province has a PGI-level regional wine. Several PDOs are effectively single estates with strict rules on varieties and yields."},"regions":[{"name":"Limburg (NL)","slug":"limburg-nl","tagline":"Marl hills, the Maas and the classic varieties.","ids":["nl-maasvallei-limburg","nl-mergelland","nl-vijlen"]},{"name":"Eastern Netherlands","slug":"eastern-netherlands","tagline":"Farm estates on sand, built on fungus-resistant grapes.","ids":["nl-achterhoek-winterswijk","nl-ambt-delden","nl-oolde"]}],"items":{"nl-achterhoek-winterswijk":{"name":"Achterhoek - Winterswijk","cat":"PDO","region":"Eastern Netherlands","created":"2020 (EU reg.)","styles":["white","red","sparkling","fortified"],"grapes":"Acolon, Cabernet Cortis, Cabertin, Johanniter, Merzling, Monarch, Pinotin, Regent, Solaris, Souvignier Gris","summary":"The PDO for Winterswijk in the eastern Achterhoek near the German border, registered in 2020, with fungus-resistant varieties grown on unusual soils that include Muschelkalk limestone, rare in the Netherlands. Wijngaard Hesselink is the main producer.","terroir":"Sand, loam and pockets of shell limestone at Winterswijk.","producers":["Wijngaard Hesselink"],"nerd_note":"Winterswijk has one of the very few Muschelkalk outcrops in the Netherlands, quarried for its stone and famous for its Triassic fossils.","rslug":"eastern-netherlands"},"nl-ambt-delden":{"name":"Ambt Delden","cat":"PDO","region":"Eastern Netherlands","created":"2019 (EU reg.)","styles":["white","red","sparkling","sweet","fortified"],"grapes":"Johanniter, Solaris, Souvignier Gris, Regent, Pinotin","summary":"A single-estate PDO in Hof van Twente, Overijssel, registered in 2019 for Wijngaard Hof van Twente, using only fungus-resistant varieties, including wine from raisined grapes.","terroir":"Sandy and loamy soils of Twente.","producers":["Wijngaard Hof van Twente"],"rslug":"eastern-netherlands"},"nl-maasvallei-limburg":{"name":"Maasvallei Limburg","cat":"PDO","region":"Limburg (NL)","created":"2017 (EU reg., with Belgium)","styles":["white","red","rose"],"grapes":"Auxerrois, Chardonnay, Pinot Blanc, Pinot Gris, Riesling, Gewürztraminer, Pinot Noir, Dornfelder, Acolon","summary":"The EU's first cross-border PDO, shared with Belgian Limburg along the Maas. On the Dutch side it includes Maasgouw (Thorn), Echt-Susteren, Roermond, Leudal, Sittard-Geleen and Stein.","terroir":"Maas gravel and sand terraces.","producers":["Wijngoed Thorn","Wijndomein Aldeneyck"],"nerd_note":"Entry also listed under Belgium; the polygon spans both countries.","rslug":"limburg-nl"},"nl-mergelland":{"name":"Mergelland","cat":"PDO","region":"Limburg (NL)","created":"2018 (EU reg.)","styles":["white","red","sparkling"],"grapes":"Auxerrois, Chardonnay, Pinot Blanc, Pinot Gris, Riesling, Müller-Thurgau, Gewürztraminer, Pinot Noir, Pinot Noir Précoce, Dornfelder","summary":"Mergelland, registered in 2018, covers nine municipalities of South Limburg around Maastricht, Valkenburg and Gulpen, on the chalky marl (mergel) that is quarried for building stone here. It allows only classic vinifera varieties, capped at 85 hl/ha, and includes the Apostelhoeve, the oldest modern Dutch vineyard.","terroir":"Cretaceous marl and loess on slopes of the Maas, Geul and Jeker valleys.","producers":["Apostelhoeve","Wijngoed Fromberg","Domein Holset","Wijngaard Hulsberg"],"nerd_note":"The marl caves (grotten) around Maastricht, such as those under Château Neercanne, have long served as natural wine cellars.","rslug":"limburg-nl"},"nl-oolde":{"name":"Oolde","cat":"PDO","region":"Eastern Netherlands","created":"2018 (EU reg.)","styles":["white","red","sparkling","fortified"],"grapes":"Solaris, Cabernet Blanc, Regent, Pinotin, Cabertin","summary":"Oolde is the single-estate PDO of Wijngoed Hof te Oolde near Laren (Lochem) in Gelderland, registered in 2018. It allows only fungus-resistant varieties, a statement of organic intent, and includes still, sparkling, semi-sparkling and liqueur wines.","terroir":"Sand and loam on the moraine ridge near Lochem.","producers":["Hof te Oolde"],"nerd_note":"One of the first PDOs anywhere based entirely on fungus-resistant (PIWI) varieties.","rslug":"eastern-netherlands"},"nl-vijlen":{"name":"Vijlen","cat":"PDO","region":"Limburg (NL)","created":"2018 (EU reg.)","styles":["white","red","sparkling"],"grapes":"Solaris, Johanniter, Souvignier Gris, Cabernet Blanc, Muscaris, Chardonnay, Pinot Gris, Pinot Noir, Cabernet Cortis, Monarch, Baron, Pinotin","summary":"Vijlen is a single-estate PDO (2018) near Vaals, at about 200 metres on the slopes of the highest hills in the Netherlands, close to the German and Belgian borders. It is farmed by Wijngaard St. Martinus with a mix of classic and fungus-resistant grapes; yields are capped at 55 hl/ha.","terroir":"Loess and gravel on south-facing slopes near the Vaalserberg.","producers":["Wijngaard St. Martinus"],"nerd_note":"Among the highest vineyards in the Netherlands.","rslug":"limburg-nl"}}};
